for s, d in S.items():
    c = json.load(open(f'sheets/{s}/cells.json')); W, H = c['size']
    sizes = '; ' + '; '.join(f"the {k.replace('_', ' ')} is about {round((v[2]-v[0])/10)} art pixels wide ({v[2]-v[0]} sheet pixels) and {round((v[3]-v[1])/10)} tall" for k, v in c['cells'].items())
    open(f'sheets/{s}/prompt.txt', 'w').write(HEAD.format(W=W, H=H, sizes=sizes, **d))
